direct_gen_code:
import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2
    for _ in range(n):
        grid.append(list(data[idx]))
        idx += 1

    # Find start and end
    start = None
    end = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # BFS
    dist = [[-1] * m for _ in range(n)]
    q = deque()
    si, sj = start
    dist[si][sj] = 0
    q.append((si, sj))
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        if (x, y) == end:
            break
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if grid[nx][ny] != '#' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

    ei, ej = end
    print(dist[ei][ej])

if __name__ == "__main__":
    solve()

final_code:
import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2
    for _ in range(n):
        grid.append(list(data[idx]))
        idx += 1

    # Find start and end
    start = None
    end = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # BFS
    dist = [[-1] * m for _ in range(n)]
    q = deque()
    si, sj = start
    dist[si][sj] = 0
    q.append((si, sj))
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        x, y = q.popleft()
        if (x, y) == end:
            break
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if grid[nx][ny] != '#' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

    ei, ej = end
    print(dist[ei][ej])

if __name__ == "__main__":
    solve()
